// Demo stand-in for "select an invoice": a synthetic, fictional EN16931
// fixture ("Unternehmen X"), embedded so this workflow is self-contained
// and runnable via `n8n execute` with no filesystem mounts. A production
// deployment replaces this node with a Form Trigger file-upload field or a
// Read/Write File From Disk node reading a real inbound invoice.
const demoInvoiceBase64 = "";

const buffer = Buffer.from(demoInvoiceBase64, "base64");
const binaryData = await this.helpers.prepareBinaryData(
  buffer,
  "invoice.xml",
  "application/xml"
);

return [
  {
    json: {
      demoNote: "Synthetic fictional EN16931 invoice (Unternehmen X) -- no real invoice or organization data.",
    },
    binary: {
      invoiceFile: binaryData,
    },
  },
];

const capabilities = $input.first().json;
const facturX = capabilities.structuredFormats["factur-x"];

const versionNote = facturX.legacyBaseline
  ? `Using LEGACY validator baseline: XSD ${facturX.xsdVersion} ` +
    `(processable profiles: ${facturX.processableLevels.join(", ")}). ` +
    `Upgrade to Factur-X 1.09.2 + Schematron is tracked separately and ` +
    `does not block this demo.`
  : `Using validator baseline: XSD ${facturX.xsdVersion}.`;

// HTTP Request and Code nodes don't automatically carry binary data
// forward from earlier nodes -- reach back to where the demo invoice was
// attached so the next node (POST /v1/invoices/process) still has it.
const invoiceBinary = $('Select Invoice (Demo Fixture)').item.binary;

return [
  {
    json: {
      versionNote,
      xsdVersion: facturX.xsdVersion,
      legacyBaseline: facturX.legacyBaseline,
      processableLevels: facturX.processableLevels,
      schematronStatus: capabilities.schematron.status,
    },
    binary: invoiceBinary,
  },
];

const response = $input.first().json;
const invoice = response.canonicalInvoice.invoice;
const document = response.canonicalInvoice.document;
const report = response.phase1ControlReport;

const failedControls = report.controls.filter(
  (c) => !["passed", "not_applicable", "not_run"].includes(c.outcome)
);

const summaryLines = [
  `Invoice ${invoice.invoiceNumber || "(missing)"} dated ${invoice.issueDate || "(missing)"}`,
  `Supplier: ${invoice.supplier.name || "(missing)"} -> Buyer: ${invoice.buyer.name || "(missing)"}`,
  `Totals: net ${invoice.totals.lineNet}, tax ${invoice.totals.taxAmount}, gross ${invoice.totals.grossAmount}, payable ${invoice.totals.payableAmount} ${invoice.currency || ""}`,
  `Detected format/profile: ${document.detectedFormat} / ${document.profile || "(none)"}`,
  `Catalog ${report.catalogVersion} / control profile ${report.controlProfileId} v${report.controlProfileVersion}`,
  ``,
  `OVERALL STATUS: ${report.status} (routing: ${report.routing})`,
  ``,
  failedControls.length === 0
    ? "All applicable controls passed."
    : `${failedControls.length} control(s) require human review:`,
  ...failedControls.map(
    (c) =>
      `  - ${c.controlId} [${c.outcome}/${c.severity}] ${c.reasonCodes.join(", ")}: ` +
      `${c.message || "(no message)"}` +
      (c.details ? ` | details: ${JSON.stringify(c.details)}` : "") +
      ` | evidence: ${c.evidenceRefs.join(", ")}`
  ),
  ``,
  `This is a Phase 1 finding for human review only -- it is not an approval,`,
  `rejection, booking, payment, or supplier communication.`,
];

return [
  {
    json: {
      reviewSummary: summaryLines.join("\n"),
      status: report.status,
      routing: report.routing,
      failedControlCount: failedControls.length,
      failedControls,
      reportId: report.reportId,
      runId: report.runId,
      sourceSha256: report.sourceSha256,
    },
  },
];
